   SET STATUS = #{f.status},
       UPT_DT = #{f.updateDate,jdbcType=TIMESTAMP}
 WHERE CP_ID = #{f.cpId}
   AND CS_ID = #{f.csId}

UPDATE TB_CHFW001
   SET URL    = #{f.url},
       STATUS = #{f.status},
       REQ_ID = #{f.requestEmployeeId},
       REQ_DT = #{f.requestDate,jdbcType=TIMESTAMP},
       UPT_DT = #{f.updateDate,jdbcType=TIMESTAMP}
 WHERE CP_ID = #{f.cpId}
   AND CS_ID = #{f.csId}

mapper.select:
